const D = { energy:.6, density:.5, glass:.55, alpha:.88, lead:.5, speed:1, scale:1, hue:212, spread:150, x:.5, y:.42, style:'cathedral', act:'sun', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const hsb2rgb=(h,s,v)=>{h=((h%360)+360)%360;s/=100;v/=100;const c=v*s,x=c*(1-Math.abs((h/60)%2-1)),m=v-c;let r,g,b;const sg=Math.floor(h/60)%6;if(sg===0){r=c;g=x;b=0;}else if(sg===1){r=x;g=c;b=0;}else if(sg===2){r=0;g=c;b=x;}else if(sg===3){r=0;g=x;b=c;}else if(sg===4){r=x;g=0;b=c;}else{r=c;g=0;b=x;}return [((r+m)*255)|0,((g+m)*255)|0,((b+m)*255)|0];};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,H=height,u=Math.min(W,H),t=K.t,dc=drawingContext;
const en=clp(P.energy,0,1);
const sp=0.45+clp(P.speed,.15,4)*0.55;
const style=P.style, hue=((P.hue%360)+360)%360, alpha=clp(P.alpha,0,1);
const isRose=style==='rose', isQuarry=style==='quarry', isCut=style==='cutline';

const cols=Math.max(3,Math.round((isRose?7:4)+clp(P.density,0,1)*(isRose?11:9)));
const rows=Math.max(2,Math.round(3+clp(P.density,0,1)*7));
const key=W+'x'+H+':'+cols+'x'+rows+':'+style+':'+P.seed+':'+P.scale.toFixed(2);

// ---- the came net: a seeded lattice, cached until size/seed/style/density change
if(!S.net||S.key!==key){
  const pts=[];
  for(let r=0;r<=rows;r++){
    const row=[];
    for(let c=0;c<=cols;c++){
      const id=r*97+c*13+1;
      let bx,by;
      if(isRose){
        const rad=(r/rows), ang=(c/cols)*TAU;
        const rr=u*0.62*Math.max(0.35,P.scale)*(rad+0.06*fr(id*3.1));
        bx=P.x*W+Math.cos(ang)*rr; by=P.y*H+Math.sin(ang)*rr*0.94;
      } else {
        const jx=isQuarry?0.10:(style==='cathedral'?0.30:0.22);
        bx=(c/cols)*W + (fr(id*3.1)-0.5)*(W/cols)*jx;
        by=(r/rows)*H + (fr(id*7.7)-0.5)*(H/rows)*jx;
        if(isQuarry) bx += (r%2)*(W/cols)*0.5;     // diamond offset courses
      }
      row.push({bx,by,p1:fr(id*11)*TAU,p2:fr(id*17)*TAU});
    }
    pts.push(row);
  }
  const tints=[];
  for(let i=0;i<rows*cols;i++) tints.push({h:fr(i*23+5),s:fr(i*29+6),v:fr(i*31+7),tx:fr(i*37+8),rm:fr(i*41+9)});
  S.net=pts; S.tints=tints; S.key=key;
}
const pts=S.net, tints=S.tints;

// ---- sample the scene behind the window
if(!S.cap||S.ckey!==W+'x'+H){
  let cw,ch;
  if(W>=H){ cw=96; ch=Math.max(8,Math.round(96*H/W)); } else { ch=96; cw=Math.max(8,Math.round(96*W/H)); }
  if(S.cap&&S.cap.remove)S.cap.remove();
  S.cap=createGraphics(cw,ch); S.cap.pixelDensity(1); S.ckey=W+'x'+H;
}
const cap=S.cap, cw=cap.width, chh=cap.height;
cap.clear(); cap.drawingContext.drawImage(dc.canvas,0,0,cw,chh);
cap.loadPixels();
const cp=cap.pixels;

// ---- act: multi-minute programs
let sunSpd=0.031, sunAmp=1.5, breathe=1;
if(P.act==='vespers'){ sunSpd=0.013; sunAmp=2.1; breathe=1.5; }
else if(P.act==='storm'){ sunSpd=0.062; sunAmp=1.1; breathe=2.4; }

// ---- the light behind the window sweeps continuously and wraps: a motion floor that
// cannot cancel on any 8s window, and the reason the glass reads as lit rather than painted
const lgx=(md(fr(2)+t*sunSpd*sp,1.5)-0.25)*W;
const lgy=H*(0.30+0.26*Math.sin(t*0.047*sp+1.1));
const lgR=u*(0.55+0.22*Math.sin(t*0.083*sp))*Math.max(0.5,P.scale);
const kick=K.pulse*0.10*en+A.bass*0.12*en;

// ---- lattice drift: the net itself breathes on two incommensurate rates
const dr=u*0.010*breathe*(0.4+0.6*en);
const px=(q)=>q.bx+Math.sin(t*0.061*sp+q.p1)*dr+Math.sin(t*0.143*sp+q.p2)*dr*0.5;
const py=(q)=>q.by+Math.cos(t*0.053*sp+q.p2)*dr+Math.sin(t*0.117*sp+q.p1)*dr*0.5;

const glassMix=clp(P.glass,0,1);
const leadW=Math.max(0.8,u*0.0045*(0.35+clp(P.lead,0,1)*1.5));
const leadC=isCut?hsb2rgb(196,60,74):hsb2rgb(hue,24,7);
noStroke();

let pi=-1;
for(let r=0;r<rows;r++){
  for(let c=0;c<cols;c++){
    pi++;
    const a=pts[r][c], b=pts[r][(c+1)%(cols+1)], d=pts[r+1][(c+1)%(cols+1)], e=pts[r+1][c];
    const bb = isRose && c===cols-1 ? pts[r][0] : b;
    const dd = isRose && c===cols-1 ? pts[r+1][0] : d;
    const ax=px(a),ay=py(a), bx2=px(bb),by2=py(bb), dx2=px(dd),dy2=py(dd), ex=px(e),ey=py(e);
    const cx=(ax+bx2+dx2+ex)*0.25, cy=(ay+by2+dy2+ey)*0.25;
    if(isRose && r===0) continue;                       // leave the rose's boss open
    // sample the scene at the pane centre
    const si=clp(Math.round(cx/W*cw-0.5),0,cw-1), sj=clp(Math.round(cy/H*chh-0.5),0,chh-1);
    const o=(sj*cw+si)*4;
    const sr=cp[o],sg=cp[o+1],sb=cp[o+2];
    // this pane's own glass
    const T=tints[pi%tints.length];
    const gh=hue+(T.h*2-1)*clp(P.spread,0,360)*0.5;
    const gc=hsb2rgb(gh, isQuarry?18+T.s*26:(isCut?0:46+T.s*44), isQuarry?74+T.v*22:(38+T.v*52));
    // light behind
    const ddx=(cx-lgx)/lgR, ddy=(cy-lgy)/lgR;
    const lit=1+ (sunAmp*en+kick)*Math.max(0,1-(ddx*ddx+ddy*ddy));
    const mixv=isCut?0.06:glassMix;
    const R=clp((sr*(1-mixv)+gc[0]*mixv)*lit,0,255);
    const G=clp((sg*(1-mixv)+gc[1]*mixv)*lit,0,255);
    const B=clp((sb*(1-mixv)+gc[2]*mixv)*lit,0,255);
    dc.beginPath(); dc.moveTo(ax,ay); dc.lineTo(bx2,by2); dc.lineTo(dx2,dy2); dc.lineTo(ex,ey); dc.closePath();
    dc.fillStyle=`rgba(${R|0},${G|0},${B|0},${(alpha*(isCut?0.30:0.92)).toFixed(3)})`;
    dc.fill();
    // reamy streaks: glass is never a flat fill
    if(!isCut && T.tx>0.42){
      dc.save(); dc.clip();
      dc.strokeStyle=`rgba(255,255,255,${(0.05+0.10*T.rm)*alpha})`;
      dc.lineWidth=Math.max(0.8,u*0.004*(0.4+T.rm));
      const sa=T.tx*TAU;
      for(let k=-1;k<=1;k++){
        dc.beginPath();
        dc.moveTo(cx-Math.cos(sa)*u*0.09+k*Math.sin(sa)*u*0.012, cy-Math.sin(sa)*u*0.09-k*Math.cos(sa)*u*0.012);
        dc.lineTo(cx+Math.cos(sa)*u*0.09+k*Math.sin(sa)*u*0.012, cy+Math.sin(sa)*u*0.09-k*Math.cos(sa)*u*0.012);
        dc.stroke();
      }
      dc.restore();
    }
    // the came, with a lit lip along its top edge
    dc.beginPath(); dc.moveTo(ax,ay); dc.lineTo(bx2,by2); dc.lineTo(dx2,dy2); dc.lineTo(ex,ey); dc.closePath();
    dc.strokeStyle=`rgba(${leadC[0]},${leadC[1]},${leadC[2]},${(alpha*(isCut?0.8:0.9)).toFixed(3)})`;
    dc.lineWidth=leadW; dc.stroke();
    if(!isCut){
      dc.strokeStyle=`rgba(210,214,220,${(0.16+0.20*en)*alpha})`;
      dc.lineWidth=Math.max(0.5,leadW*0.34);
      dc.beginPath(); dc.moveTo(ax,ay-leadW*0.3); dc.lineTo(bx2,by2-leadW*0.3); dc.stroke();
    }
  }
}

dc.globalAlpha=1; dc.globalCompositeOperation='source-over';
blendMode(BLEND); dc.shadowBlur=0; noStroke();
